// Public Webador presentation mode: hide editing UI without removing map functionality.
// This is a presentation setting, not authentication or write-access security.
const HS2_PUBLIC_DISPLAY = new URLSearchParams(window.location.search).get('display') === '1';
if (HS2_PUBLIC_DISPLAY) {
  document.documentElement.classList.add('webador-public');
  const publicStyle = document.createElement('style');
  publicStyle.id = 'hs2-public-display-style';
  publicStyle.textContent = `
    .webador-public #pinEditor,
    .webador-public #tunnelEditor,
    .webador-public .edit-location,
    .webador-public #csvImportControl,
    .webador-public #csvImportHelp,
    .webador-public #photoImportSection,
    .webador-public #reloadRouteGeojson,
    .webador-public #traceFallback { display: none !important; }
  `;
  document.head.appendChild(publicStyle);
}


// Public defaults are published as a repository JSON file, not stored only in the editor's browser.
const HS2_PUBLIC_DEFAULTS={
  version:1,center:[51.5340,-0.2050],zoom:15,distanceSource:'published2013both',
  layers:{properties:true,editableTunnel:true,buffer:true,zone:false,
    published2013:true,queenWard:true,safeguardingSubsurface:false,
    safeguardingSurface:false,safeguardingLimits:false}
};
let hs2PublicSettings=structuredClone(HS2_PUBLIC_DEFAULTS);
let hs2SettingsReady=false;
let hs2PublishedReady=false;
let hs2SettingsLoad=fetch('public-settings.json',{cache:'no-store'})
  .then(async r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json()})
  .then(data=>{
    if(!data||data.version!==1||!Array.isArray(data.center)||data.center.length!==2
       ||!data.center.every(Number.isFinite)||Math.abs(data.center[0])>90
       ||Math.abs(data.center[1])>180||!Number.isInteger(data.zoom)
       ||data.zoom<1||data.zoom>19||!data.layers||typeof data.layers!=='object')
       throw Error('Invalid public settings');
    hs2PublicSettings={...HS2_PUBLIC_DEFAULTS,...data,layers:{...HS2_PUBLIC_DEFAULTS.layers,...data.layers}};
    return hs2PublicSettings;
  }).catch(e=>{console.warn('Using built-in public defaults:',e.message);return hs2PublicSettings})
  .finally(()=>{hs2SettingsReady=true;if(HS2_PUBLIC_DISPLAY)hs2ApplyPublicSettings();});
function hs2LayerToggle(id,visible){
  const input=document.getElementById(id);
  if(!input||input.disabled)return;
  input.checked=!!visible;
  input.dispatchEvent(new Event('change',{bubbles:true}));
}
function hs2ApplyPublicSettings(){
  if(!hs2SettingsReady)return;
  const s=hs2PublicSettings,l=s.layers;
  const ids={properties:'showHouses',editableTunnel:'showTunnel',buffer:'showCorridor',
    zone:'showZone',published2013:'showPublishedCentreline2013',queenWard:'showWardBoundary',
    safeguardingSubsurface:'showSubsurface2019',
    safeguardingSurface:'showSurface2019',
    safeguardingLimits:'showLimits2019'};
  Object.entries(ids).forEach(([key,id])=>{if(typeof l[key]==='boolean')hs2LayerToggle(id,l[key]);});
  const select=document.getElementById('propertyDistanceSource');
  if(select&&s.distanceSource&&Array.from(select.options).some(o=>o.value===s.distanceSource&&!o.disabled)){
    select.value=s.distanceSource;select.dispatchEvent(new Event('change',{bubbles:true}));
  }
  openingFitActive=false;
  if(openingFitObserver)openingFitObserver.disconnect();
  clearTimeout(openingFitTimer);
  map.invalidateSize({pan:false});
  map.setView(s.center,s.zoom,{animate:false});
}
function hs2BuildPublicSettingsPanel(){
  if(HS2_PUBLIC_DISPLAY)return;
  const aside=document.querySelector('main aside');
  if(!aside)return;
  const section=document.createElement('section');section.id='publicSettingsEditor';
  section.innerHTML=`<h2>Public Map Settings</h2>
    <p class="hint">Set the map view and layer visibility here, then export the settings to your GitHub repository. The Webador map reads the published file.</p>
    <label>Opening zoom <input id="publicZoom" type="number" min="1" max="19" step="1"></label>
    <p class="hint">Opening centre: <span id="publicCentre"></span></p>
    <button type="button" id="publicCapture">Use current map view</button>
    <div id="publicLayerChecks"></div>
    <label>Property distance source <select id="publicDistance">
      <option value="published2013both">Nearest of both published 2013 alignments</option>
      <option value="published2013">Published HS2 DOWN MAIN (2013)</option>
      <option value="editable">Editable tunnel route</option>
    </select></label>
    <button type="button" id="publicPreview">Preview public defaults</button>
    <button type="button" id="publicExport">Export public-settings.json</button>
    <button type="button" id="publicCopy" style="margin-top:6px">Show / copy settings (Safari fallback)</button>
    <div id="publicJsonFallback" hidden><p class="hint">If Safari does not download the file, copy the text below into a plain-text file named <strong>public-settings.json</strong>.</p><textarea id="publicJsonText" rows="12" spellcheck="false" style="width:100%;font-family:monospace"></textarea><button type="button" id="publicSelectAll">Select all JSON</button></div>
    <p id="publicSettingsStatus" class="hint" role="status"></p>`;
  aside.insertBefore(section,aside.firstChild);
  const names={properties:'Property pinpoints',editableTunnel:'Editable tunnel routes',
    buffer:'30 m indicative buffer',zone:'Tunnel zone',published2013:'Published 2013 alignments',
    queenWard:'Queen’s Park boundary',safeguardingSubsurface:'Sub-surface safeguarding',
    safeguardingSurface:'Surface safeguarding',safeguardingLimits:'Safeguarding limits'};
  const checks=section.querySelector('#publicLayerChecks');
  Object.entries(names).forEach(([key,name])=>{
    const label=document.createElement('label');label.className='check';
    const input=document.createElement('input');input.type='checkbox';input.dataset.publicLayer=key;
    label.append(input,document.createTextNode(' '+name));checks.append(label);
  });
  const status=section.querySelector('#publicSettingsStatus');
  function populate(){
    section.querySelector('#publicZoom').value=hs2PublicSettings.zoom;
    section.querySelector('#publicCentre').textContent=hs2PublicSettings.center.map(x=>x.toFixed(6)).join(', ');
    section.querySelector('#publicDistance').value=hs2PublicSettings.distanceSource;
    section.querySelectorAll('[data-public-layer]').forEach(i=>i.checked=!!hs2PublicSettings.layers[i.dataset.publicLayer]);
  }
  function collect(){
    const zoom=Number(section.querySelector('#publicZoom').value);
    if(!Number.isInteger(zoom)||zoom<1||zoom>19)throw Error('Zoom must be between 1 and 19');
    const layers={...hs2PublicSettings.layers};
    section.querySelectorAll('[data-public-layer]').forEach(i=>layers[i.dataset.publicLayer]=i.checked);
    return {...hs2PublicSettings,zoom,layers,distanceSource:section.querySelector('#publicDistance').value};
  }
  section.querySelector('#publicCapture').onclick=()=>{
    hs2PublicSettings.center=[+map.getCenter().lat.toFixed(7),+map.getCenter().lng.toFixed(7)];
    hs2PublicSettings.zoom=map.getZoom();populate();status.textContent='Current map centre and zoom captured.';
  };
  section.querySelector('#publicPreview').onclick=()=>{
    try{hs2PublicSettings=collect();hs2ApplyPublicSettings();status.textContent='Preview applied. These settings are not published until the JSON file is uploaded.'}
    catch(e){status.textContent=e.message}
  };
  function exportText(){
    hs2PublicSettings=collect();
    return JSON.stringify(hs2PublicSettings,null,2)+'\n';
  }
  function showFallback(json){
    const wrap=section.querySelector('#publicJsonFallback');
    const area=section.querySelector('#publicJsonText');
    wrap.hidden=false;area.value=json;
    status.textContent='Settings shown below. If no download appears, select and copy the JSON into a file named public-settings.json.';
  }
  section.querySelector('#publicExport').onclick=()=>{
    try{
      const json=exportText();
      // Safari can refuse blob: downloads with WebKitBlobResource error 1.
      // A data: URL with a download attribute avoids the blob: resource entirely.
      const a=document.createElement('a');
      a.href='data:application/json;charset=utf-8,'+encodeURIComponent(json);
      a.download='public-settings.json';
      document.body.appendChild(a);a.click();a.remove();
      showFallback(json);
      status.textContent='Download requested. If Safari does not save the file, use the JSON shown below.';
    }catch(e){status.textContent=e.message}
  };
  section.querySelector('#publicCopy').onclick=()=>{
    try{showFallback(exportText());section.querySelector('#publicJsonText').select()}
    catch(e){status.textContent=e.message}
  };
  section.querySelector('#publicSelectAll').onclick=()=>section.querySelector('#publicJsonText').select();
  hs2SettingsLoad.then(()=>{populate();status.textContent='Repository defaults loaded. Move the map, capture the view, then export.'});
}

const map=L.map('map',{zoomControl:true}).setView([51.5340,-0.2050],15);
// A real Leaflet control keeps the legend in the control pane, above tile and overlay panes.
const hs2HotspotLegendControl=L.control({position:'bottomright'});
hs2HotspotLegendControl.onAdd=function(){
 const el=L.DomUtil.create('div','leaflet-control hs2-floating-hotspot-legend');
 el.id='hs2FloatingHotspotLegend';
 el.setAttribute('role','note');
 el.setAttribute('aria-label','Hotspot density colour legend');
 el.innerHTML='<strong>Hotspot density</strong><div class="hs2-density-gradient" aria-hidden="true"></div><div class="hs2-density-labels"><span>Lower</span><span>Higher</span></div><p>Concentration of recorded properties, not damage severity.</p>';
 L.DomEvent.disableClickPropagation(el);
 L.DomEvent.disableScrollPropagation(el);
 return el;
};
hs2HotspotLegendControl.addTo(map);
function updateHs2HotspotLegend(){
 const el=document.getElementById('hs2FloatingHotspotLegend');
 if(!el)return;
 const enabled=document.getElementById('showHotspotLegend');
 const layer=document.getElementById('showIncidentAreas');
 const style=document.getElementById('incidentStyle');
 const show=!!(enabled?.checked&&layer?.checked&&style?.value==='heatmap');
 el.hidden=!show;
 el.style.display=show?'':'none';
 el.setAttribute('aria-hidden',String(!show));
 const layered=document.getElementById('incidentDataset')?.value==='layered';
 const both=document.getElementById('incidentDataset')?.value==='both';
 const unaffected=document.getElementById('incidentDataset')?.value==='unaffected';
 el.setAttribute('aria-label',layered?'Layered comparison of affected and unaffected hotspot density':both?'Combined affected and unaffected hotspot density':unaffected?'Unaffected properties hotspot density':'Reported damage hotspot density');
 el.classList.toggle('hs2-combined-legend',both||layered);
 el.querySelector('strong').textContent=layered?'Layered Comparison — Affected & Unaffected':both?'Combined — Affected & Unaffected':unaffected?'Unaffected Properties — Hotspot Density':'Reported Damage — Hotspot Density';
 // Keep the display-style selector and sidebar colour-scale title in sync too.
 const heatmapOption=document.querySelector('#incidentStyle option[value="heatmap"]');
 if(heatmapOption)heatmapOption.textContent=layered?'Hotspot density — layered affected & unaffected':both?'Hotspot density — combined affected & unaffected':unaffected?'Hotspot density — unaffected properties':'Hotspot density — reported damage';
 const sidebarScale=document.querySelector('.hs2-density-scale');
 if(sidebarScale){
  let heading=sidebarScale.previousElementSibling;
  if(!heading||!heading.classList.contains('hs2-density-scale-title')){
   heading=document.createElement('div');
   heading.className='hs2-density-scale-title';
   heading.style.cssText='font-weight:600;margin:8px 0 4px';
   sidebarScale.parentNode.insertBefore(heading,sidebarScale);
  }
  let secondScale=sidebarScale.parentNode.querySelector('.hs2-unaffected-density-scale');
  if(layered&&!secondScale){
   secondScale=document.createElement('div');secondScale.className='hs2-unaffected-density-scale';
   secondScale.innerHTML='<div style="font-weight:600;margin:7px 0 3px">Unaffected — density</div><div style="height:11px;border-radius:5px;background:linear-gradient(to right,#f9d5e9,#f39ac9,#e34da7,#b71b82,#85166f,#6b135e)"></div>';
   sidebarScale.insertAdjacentElement('afterend',secondScale);
  }
  if(secondScale){secondScale.hidden=!layered;secondScale.style.display=layered?'':'none';}
  heading.textContent=layered?'Affected — density (lower layer)':both?'Hotspot density — affected & unaffected':unaffected?'Hotspot density — unaffected':'Hotspot density — affected';
  sidebarScale.style.background=''; // Standalone datasets share the original rainbow density key.
 }

 // In layered mode show two actual colour keys, one per dataset.
 let layeredKeys=el.querySelector('.hs2-layered-colour-keys');
 if(layered&&!layeredKeys){
  layeredKeys=document.createElement('div');
  layeredKeys.className='hs2-layered-colour-keys';
  layeredKeys.style.cssText='display:grid;gap:5px;margin:7px 0;font-size:12px';
  layeredKeys.innerHTML='<div><b>Affected (lower)</b><div style="height:10px;border-radius:5px;background:linear-gradient(to right,#3146b8,#00b8e4,#3ad46b,#f5ed43,#ff9327,#d7191c)"></div></div><div><b>Unaffected (upper)</b><div style="height:10px;border-radius:5px;background:linear-gradient(to right,#f9d5e9,#f39ac9,#e34da7,#b71b82,#85166f,#6b135e)"></div></div>';
  el.querySelector('.hs2-density-gradient').insertAdjacentElement('beforebegin',layeredKeys);
 }
 if(layeredKeys){layeredKeys.hidden=!layered;layeredKeys.style.display=layered?'grid':'none';}
 if(layeredKeys&&!layeredKeys.querySelector('.hs2-contour-key'))layeredKeys.insertAdjacentHTML('beforeend','<div class="hs2-contour-key" style="font-size:11px"><span style="color:#c52b35;font-weight:700">━━</span> Affected contour &nbsp; <span style="color:#74206e;font-weight:700">┄┄</span> Unaffected contour (when enabled)</div>');
 const singleGradient=el.querySelector('.hs2-density-gradient');
 if(singleGradient)singleGradient.style.display=layered?'none':'';
 if(singleGradient)singleGradient.style.background=''; // Layered comparison keeps its separate pink-plum key above.
 el.querySelector('.hs2-density-labels').innerHTML=layered?'<span>Low density</span><span>High density</span>':both?'<span>Red: reported damage</span><span>Blue: unaffected</span>':'<span>Lower</span><span>Higher</span>';
 el.querySelector('p').textContent=layered?'Affected: original rainbow scale. Unaffected: pink to deep plum. Transparency may mix colours; this does not establish causation.':both?'Green indicates overlapping concentrations. Colours do not indicate damage severity or HS2 causation.':(unaffected?'Density of explicitly unaffected property records.':'Density of properties reporting damage.')+' Not damage severity or proof of HS2 causation.';
}
['showHotspotLegend','showIncidentAreas','incidentStyle','incidentDataset'].forEach(id=>
 document.getElementById(id)?.addEventListener('change',updateHs2HotspotLegend));
updateHs2HotspotLegend();


// Home control: return to the map's original Queen's Park view.
const HS2_HOME_CENTER=[51.5340,-0.2050];
const HS2_HOME_ZOOM=15;
const homeControl=L.control({position:'topleft'});
homeControl.onAdd=function(){
  const container=L.DomUtil.create('div','leaflet-bar leaflet-control');
  const link=L.DomUtil.create('a','',container);
  link.href='#';
  link.title='Return to Queen’s Park';
  link.setAttribute('aria-label','Return to Queen’s Park');
  link.setAttribute('role','button');
  link.textContent='⌂';
  link.style.fontSize='23px';
  link.style.fontWeight='bold';
  link.style.lineHeight='30px';
  L.DomEvent.disableClickPropagation(container);
  L.DomEvent.on(link,'click',L.DomEvent.stop).on(link,'click',()=>{
    map.setView(HS2_HOME_CENTER,HS2_HOME_ZOOM,{animate:true});
  });
  return container;
};
homeControl.addTo(map);

// OpenStreetMap standard raster tiles. OSMF now specifies this exact host
// (without a/b/c subdomains) and requires normal browser referrer behaviour.
const osmTiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{
  maxZoom:19,
  attribution:'&copy; OpenStreetMap contributors',
  crossOrigin:false,
  referrerPolicy:'strict-origin-when-cross-origin'
}).addTo(map);

// Background map selector (no API keys required).
// These are third-party public tile services; their usage policies and availability apply.
const aerialTiles=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{
  maxZoom:19,
  attribution:'Tiles &copy; Esri and its imagery contributors'
});
const humanitarianTiles=L.tileLayer('https://{s}.tile.openstreetmap.fr/hot/{z}/{x}/{y}.png',{
  maxZoom:19,
  subdomains:'abc',
  attribution:'&copy; OpenStreetMap contributors, tiles by HOT/OSM France'
});
const topoTiles=L.tileLayer('https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png',{
  maxZoom:17,
  subdomains:'abc',
  attribution:'&copy; OpenStreetMap contributors, SRTM | map style &copy; OpenTopoMap (CC-BY-SA)'
});
const hs2BaseLayerControl=L.control.layers({
  'Street map — OpenStreetMap':osmTiles,
  'Aerial imagery — Esri':aerialTiles,
  'Humanitarian street map':humanitarianTiles,
  'Topographic map':topoTiles
},null,{position:'topright',collapsed:true}).addTo(map);

