// HS2 monitoring locations: published May–August 2026 metadata, not a live inventory.
// Layer registration is deliberately independent of property and tunnel filters.
(function installHS2MonitorLayers(){
  const sourceUrl='https://www.data.gov.uk/dataset/24542ae7-dd44-444f-b259-871c4cc43b5e/environmental-monitoring-data';
  const dataset=HS2_MONITOR_LOCATIONS;
  const escaped=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const noise=L.layerGroup(),vibration=L.layerGroup();
  const colours={Noise:'#1769aa',Vibration:'#7937a8'};
  const icon=type=>L.divIcon({className:'hs2-monitor-icon',iconSize:[18,18],iconAnchor:[9,9],popupAnchor:[0,-10],html:type==='Noise'
    ?'<span aria-hidden="true" style="display:block;width:14px;height:14px;margin:2px;background:#1769aa;border:2px solid white;border-radius:50%;box-shadow:0 0 0 1px #16466c;box-sizing:border-box"></span>'
    :'<span aria-hidden="true" style="display:block;width:12px;height:12px;margin:3px;background:#7937a8;border:2px solid white;transform:rotate(45deg);box-shadow:0 0 0 1px #48216b;box-sizing:border-box"></span>'});
  const counts={Noise:0,Vibration:0};
  dataset.features.forEach(feature=>{
    const p=feature.properties,[lon,lat]=feature.geometry.coordinates,type=p.monitor_type;
    if(!Number.isFinite(lon)||!Number.isFinite(lat)||!(type in counts))return;
    const label=type+' monitor '+p.monitor_id+(p.historical_only?' (historical)':'');
    const popup='<div style="max-width:290px;line-height:1.45"><strong style="color:'+colours[type]+'">'+escaped(label)+'</strong>'+
      '<p>'+[p.location,p.address].filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).map(escaped).join('<br>')+'</p>'+
      '<p><strong>Area:</strong> '+escaped(p.area)+'<br><strong>Worksite:</strong> '+escaped(p.worksite)+'</p>'+
      '<p><strong>Listed in:</strong> '+escaped(p.months.join(', '))+'<br><strong>References:</strong> '+escaped(p.monitor_references.join(', '))+'<br><strong>National Grid:</strong> '+p.easting+' E, '+p.northing+' N</p>'+
      '<p>'+(p.historical_only?'<strong>Historical location: not listed at these coordinates in August.</strong> ':'')+'Published monitor location. Current activity and position have not been independently verified. This pin does not show readings, damage or ground settlement.</p>'+
      '<a href="'+sourceUrl+'" target="_blank" rel="noopener noreferrer">HS2 source data</a></div>';
    L.marker([lat,lon],{icon:icon(type),title:label,alt:label,riseOnHover:true})
      .bindTooltip(label+' — '+escaped(p.location||p.area)).bindPopup(popup)
      .addTo(type==='Noise'?noise:vibration);
    counts[type]++;
  });
  hs2BaseLayerControl.addOverlay(noise,'<span style="color:#1769aa">●</span> Noise monitors — May–Aug 2026 ('+counts.Noise+')');
  hs2BaseLayerControl.addOverlay(vibration,'<span style="color:#7937a8">◆</span> Vibration monitors — May–Aug 2026 ('+counts.Vibration+')');
  // Both overlays start off, preserving the user's existing map view and layers.
})();

