// Continuous screen-space Gaussian kernels; no grid binning or square-cell boundaries.
const SmoothIncidentDensity=L.Layer.extend({
 initialize(samples,options){this.samples=samples;this.options=options;},
 onAdd(map){
  this._map=map;
  this._canvas=L.DomUtil.create('canvas','hs2-smooth-density',map.getPane('incidentAreasPane'));
  this._canvas.style.cssText='position:absolute;pointer-events:none;';
  map.on('moveend resize zoomend',this._draw,this);
  this._draw();
 },
 onRemove(map){map.off('moveend resize zoomend',this._draw,this);this._canvas.remove();},
 _draw(){
  const map=this._map,sz=map.getSize(),scale=0.5;
  if(!sz.x||!sz.y)return;
  const w=Math.ceil(sz.x*scale),h=Math.ceil(sz.y*scale),canvas=this._canvas;
  canvas.width=w;canvas.height=h;
  canvas.style.width=sz.x+'px';canvas.style.height=sz.y+'px';
  const corner=map.containerPointToLayerPoint([0,0]);
  L.DomUtil.setPosition(canvas,corner);
  const ctx=canvas.getContext('2d',{willReadFrequently:true});
  const latitude=this.samples.reduce((a,p)=>a+p[0],0)/this.samples.length;
  const metersPerPixel=40075016.686*Math.cos(latitude*Math.PI/180)/(256*Math.pow(2,map.getZoom()));
  const radius=Math.max(8,Math.min(230,this.options.radiusMeters/metersPerPixel))*scale;
  // Additive alpha makes every incident contribute continuously across its circular kernel.
  ctx.globalCompositeOperation='lighter';
  for(const [lat,lng] of this.samples){
   const p=map.latLngToContainerPoint([lat,lng]),x=p.x*scale,y=p.y*scale;
   if(x < -radius||x>w+radius||y < -radius||y>h+radius)continue;
   const g=ctx.createRadialGradient(x,y,0,x,y,radius);
   g.addColorStop(0,'rgba(255,255,255,0.22)');
   g.addColorStop(0.25,'rgba(255,255,255,0.16)');
   g.addColorStop(0.55,'rgba(255,255,255,0.08)');
   g.addColorStop(1,'rgba(255,255,255,0)');
   ctx.fillStyle=g;ctx.fillRect(x-radius,y-radius,radius*2,radius*2);
  }
  const data=ctx.getImageData(0,0,w,h),pixels=data.data;
  const defaultStops=[[0.05,[49,70,184]],[0.20,[0,184,228]],[0.38,[58,212,107]],[0.58,[245,237,67]],[0.78,[255,147,39]],[1,[215,25,28]]];
  // Pink-to-plum scale separates explicitly unaffected density from the affected rainbow palette.
  const coolStops=[[0.05,[249,213,233]],[0.20,[243,154,201]],[0.38,[227,77,167]],[0.58,[183,27,130]],[0.78,[133,22,111]],[1,[107,19,94]]];
  const stops=this.options.palette==='layered-unaffected'?coolStops:defaultStops;
  const palette=this.options.palette;
  // In combined mode, red and blue layers retain their own identity.
  // Alpha increases with density, while overlap is calculated as green.

  for(let i=0;i<pixels.length;i+=4){
   const density=pixels[i+3]/255;
   if(density<0.035){pixels[i+3]=0;continue;}
   const t=Math.min(1,density/0.75);
   let j=1;while(j<stops.length-1&&t>stops[j][0])j++;
   const [a,ca]=stops[j-1],[b,cb]=stops[j],f=Math.max(0,Math.min(1,(t-a)/(b-a)));
   if(palette==='damage'||palette==='unaffected'){
    const col=palette==='damage'?[216,52,49]:[28,114,210];
    pixels[i]=col[0];pixels[i+1]=col[1];pixels[i+2]=col[2];
    pixels[i+3]=Math.round(255*this.options.opacity*Math.min(1,(density-0.035)/0.50));
   }else{
    pixels[i]=ca[0]+(cb[0]-ca[0])*f;
    pixels[i+1]=ca[1]+(cb[1]-ca[1])*f;
    pixels[i+2]=ca[2]+(cb[2]-ca[2])*f;
    pixels[i+3]=Math.round(255*this.options.opacity*Math.min(1,(density-0.035)/0.12));
   }
  }
  ctx.globalCompositeOperation='source-over';ctx.putImageData(data,0,0);
 }
});

// Draw mathematically derived density contours from the same Gaussian-like kernel
// used by SmoothIncidentDensity. The contours are a visual threshold, NOT
// boundaries of affected properties, subsidence, or HS2 impact.
const HS2DensityContours=L.Layer.extend({
 initialize(affected,unaffected,options){this.affected=affected;this.unaffected=unaffected;this.options=options;},
 onAdd(map){
  this._map=map;
  this._canvas=L.DomUtil.create('canvas','hs2-density-contours',map.getPane('incidentAreasPane'));
  this._canvas.style.cssText='position:absolute;pointer-events:none;';
  map.on('moveend resize zoomend',this._draw,this);this._draw();
 },
 onRemove(map){map.off('moveend resize zoomend',this._draw,this);this._canvas.remove();},
 _draw(){
  const map=this._map,sz=map.getSize(),scale=0.5;
  if(!sz.x||!sz.y)return;
  const w=Math.ceil(sz.x*scale),h=Math.ceil(sz.y*scale),c=this._canvas;
  c.width=w;c.height=h;c.style.width=sz.x+'px';c.style.height=sz.y+'px';
  L.DomUtil.setPosition(c,map.containerPointToLayerPoint([0,0]));
  const ctx=c.getContext('2d');
  const all=this.affected.concat(this.unaffected);
  if(!all.length)return;
  const lat=all.reduce((a,p)=>a+p[0],0)/all.length;
  const mpp=40075016.686*Math.cos(lat*Math.PI/180)/(256*Math.pow(2,map.getZoom()));
  const radius=Math.max(8,Math.min(230,this.options.radiusMeters/mpp))*scale;
  const threshold=0.75*this.options.threshold/100;
  const gridStep=3; // half-resolution pixels: 6 screen pixels per contour cell
  const cols=Math.ceil(w/gridStep)+1,rows=Math.ceil(h/gridStep)+1;
  function field(samples){
   const off=document.createElement('canvas');off.width=w;off.height=h;
   const gctx=off.getContext('2d',{willReadFrequently:true});
   gctx.globalCompositeOperation='lighter';
   for(const [latitude,longitude] of samples){
    const p=map.latLngToContainerPoint([latitude,longitude]);
    const x=p.x*scale,y=p.y*scale;
    if(x < -radius||x>w+radius||y < -radius||y>h+radius)continue;
    const grad=gctx.createRadialGradient(x,y,0,x,y,radius);
    grad.addColorStop(0,'rgba(255,255,255,0.22)');
    grad.addColorStop(.25,'rgba(255,255,255,0.16)');
    grad.addColorStop(.55,'rgba(255,255,255,0.08)');
    grad.addColorStop(1,'rgba(255,255,255,0)');
    gctx.fillStyle=grad;gctx.fillRect(x-radius,y-radius,radius*2,radius*2);
   }
   const alpha=gctx.getImageData(0,0,w,h).data;
   const values=new Float32Array(cols*rows);
   for(let gy=0;gy<rows;gy++)for(let gx=0;gx<cols;gx++){
    const x=Math.min(w-1,gx*gridStep),y=Math.min(h-1,gy*gridStep);
    values[gy*cols+gx]=alpha[(y*w+x)*4+3]/255;
   }
   return values;
  }
  // Marching squares; linear interpolation avoids blocky boundaries.
  function draw(samples,colour,dashed){
   if(!samples.length)return;
   const v=field(samples);
   ctx.beginPath();
   const edge=(ax,ay,av,bx,by,bv)=>{
    const t=Math.max(0,Math.min(1,(threshold-av)/((bv-av)||1e-9)));
    return [ax+(bx-ax)*t,ay+(by-ay)*t];
   };
   for(let y=0;y<rows-1;y++)for(let x=0;x<cols-1;x++){
    const i=y*cols+x;
    const a=v[i],b=v[i+1],d=v[i+cols],e=v[i+cols+1];
    const x0=x*gridStep,y0=y*gridStep,x1=(x+1)*gridStep,y1=(y+1)*gridStep;
    const crosses=[];
    if((a>=threshold)!==(b>=threshold))crosses.push(edge(x0,y0,a,x1,y0,b));
    if((b>=threshold)!==(e>=threshold))crosses.push(edge(x1,y0,b,x1,y1,e));
    if((e>=threshold)!==(d>=threshold))crosses.push(edge(x1,y1,e,x0,y1,d));
    if((d>=threshold)!==(a>=threshold))crosses.push(edge(x0,y1,d,x0,y0,a));
    for(let j=0;j+1<crosses.length;j+=2){
     ctx.moveTo(...crosses[j]);ctx.lineTo(...crosses[j+1]);
    }
   }
   ctx.strokeStyle=colour;ctx.lineWidth=2.4*scale;
   ctx.setLineDash(dashed?[7*scale,5*scale]:[]);
   ctx.lineJoin='round';ctx.stroke();ctx.setLineDash([]);
  }
  draw(this.affected,'#c52b35',false);
  draw(this.unaffected,'#74206e',true);
 }
});
// Combined heatmap: calculate both density fields separately and colour their intersection green.
// Unlike CSS blending red and blue, this produces a real green overlap without recolouring either dataset.
const CombinedIncidentDensity=SmoothIncidentDensity.extend({
 initialize(affected,unaffected,options){
  this.affected=affected;this.unaffected=unaffected;
  this.samples=affected.concat(unaffected);this.options=options;
 },
 _draw(){
  const map=this._map,sz=map.getSize(),scale=0.5;
  if(!sz.x||!sz.y||!this.samples.length)return;
  const w=Math.ceil(sz.x*scale),h=Math.ceil(sz.y*scale),canvas=this._canvas;
  canvas.width=w;canvas.height=h;
  canvas.style.width=sz.x+'px';canvas.style.height=sz.y+'px';
  L.DomUtil.setPosition(canvas,map.containerPointToLayerPoint([0,0]));
  const latitude=this.samples.reduce((n,p)=>n+p[0],0)/this.samples.length;
  const metersPerPixel=40075016.686*Math.cos(latitude*Math.PI/180)/(256*Math.pow(2,map.getZoom()));
  const radius=Math.max(8,Math.min(230,this.options.radiusMeters/metersPerPixel))*scale;
  function density(samples){
   const c=document.createElement('canvas');c.width=w;c.height=h;
   const ctx=c.getContext('2d',{willReadFrequently:true});
   ctx.globalCompositeOperation='lighter';
   for(const [lat,lng] of samples){
    const p=map.latLngToContainerPoint([lat,lng]),x=p.x*scale,y=p.y*scale;
    if(x < -radius||x>w+radius||y < -radius||y>h+radius)continue;
    const g=ctx.createRadialGradient(x,y,0,x,y,radius);
    g.addColorStop(0,'rgba(255,255,255,0.22)');
    g.addColorStop(0.25,'rgba(255,255,255,0.16)');
    g.addColorStop(0.55,'rgba(255,255,255,0.08)');
    g.addColorStop(1,'rgba(255,255,255,0)');
    ctx.fillStyle=g;ctx.fillRect(x-radius,y-radius,radius*2,radius*2);
   }
   return ctx.getImageData(0,0,w,h).data;
  }
  const red=density(this.affected),blue=density(this.unaffected);
  const ctx=canvas.getContext('2d',{willReadFrequently:true});
  const image=ctx.createImageData(w,h),px=image.data;
  // Match the original individual heatmaps: no minimum halo or opacity floor.
  // Both independent density fields use exactly the same kernel and threshold.
  const threshold=0.035;
  const fullStrength=0.50;
  for(let i=0;i<px.length;i+=4){
   const rawR=red[i+3]/255,rawB=blue[i+3]/255;
   const r=Math.min(1,Math.max(0,(rawR-threshold)/fullStrength));
   const b=Math.min(1,Math.max(0,(rawB-threshold)/fullStrength));
   const peak=Math.max(r,b);
   if(peak<=0)continue;
   // Green is reserved for genuine overlapping concentrations, not faint edges.
   const overlap=(r>=0.16&&b>=0.16)?Math.min(1,Math.min(r,b)/Math.max(r,b)):0;
   const mix=overlap>0?Math.min(1,overlap*1.25):0;
   const base=r>=b?[216,52,49]:[28,114,210];
   const green=[40,166,89];
   px[i]=Math.round(base[0]*(1-mix)+green[0]*mix);
   px[i+1]=Math.round(base[1]*(1-mix)+green[1]*mix);
   px[i+2]=Math.round(base[2]*(1-mix)+green[2]*mix);
   px[i+3]=Math.round(255*this.options.opacity*peak);
  }
  ctx.putImageData(image,0,0);
 }
});
// Synchronized comparison of reported damage and explicitly unaffected properties.
let comparisonMaps=null,comparisonLayers=[],comparisonSyncing=false;
function ensureComparisonMaps(){
 if(comparisonMaps)return;
 const create=id=>{
  const m=L.map(id,{zoomControl:true,scrollWheelZoom:false}).setView(map.getCenter(),map.getZoom());
  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(m);
  m.createPane('incidentAreasPane');m.getPane('incidentAreasPane').style.zIndex='590';
  m.getPane('incidentAreasPane').style.pointerEvents='none';return m;
 };
 comparisonMaps=[create('compareDamageMap'),create('compareUnaffectedMap')];
 comparisonMaps.forEach((m,i)=>m.on('moveend',()=>{
  if(comparisonSyncing)return;
  comparisonSyncing=true;comparisonMaps[1-i].setView(m.getCenter(),m.getZoom(),{animate:false});comparisonSyncing=false;
 }));
}
function refreshHotspotComparison(){
 if(!document.getElementById('hotspotComparison')?.open)return;
 ensureComparisonMaps();comparisonMaps.forEach(m=>m.invalidateSize());
 const radius=Number(document.getElementById('incidentRadius')?.value||75);
 const opacity=Number(document.getElementById('incidentOpacity')?.value||55)/100;
 const groups=[properties.filter(reportedIncident),properties.filter(unaffectedIncident)];
 comparisonLayers.forEach((layer,i)=>{if(layer)comparisonMaps[i].removeLayer(layer)});
 comparisonLayers=groups.map((group,i)=>{
  document.getElementById(i?'compareUnaffectedCount':'compareDamageCount').textContent=`(${group.length})`;
  return group.length?new SmoothIncidentDensity(group.map(p=>[+p.latitude,+p.longitude]),{radiusMeters:radius,opacity}).addTo(comparisonMaps[i]):null;
 });
}
document.getElementById('hotspotComparison')?.addEventListener('toggle',refreshHotspotComparison);
for(const id of ['incidentRadius','incidentOpacity'])document.getElementById(id)?.addEventListener('input',refreshHotspotComparison);
function reportedIncident(p){
 const damage=String(p.damage||'').trim();
 return isPropertyIncluded(p)&&hs2PermissionVisible(p)&&isLocalCoordinate(p.latitude,p.longitude)&&!!damage&&!isUnaffected(p);
}
function unaffectedIncident(p){
 return isPropertyIncluded(p)&&hs2PermissionVisible(p)&&isLocalCoordinate(p.latitude,p.longitude)&&isUnaffected(p);
}
function refreshIncidentAreas(){
 incidentAreaLayer.clearLayers();
 if(incidentHeatLayer){map.removeLayer(incidentHeatLayer);incidentHeatLayer=null;}
 combinedIncidentLayers.forEach(layer=>map.removeLayer(layer));combinedIncidentLayers=[];
 const toggle=document.getElementById('showIncidentAreas');
 const note=document.getElementById('incidentAreaStatus');
 if(!toggle||!toggle.checked){if(note)note.textContent='Layer switched off.';return;}
 const radius=Number(document.getElementById('incidentRadius')?.value||75);
 const opacity=Number(document.getElementById('incidentOpacity')?.value||55)/100;
 const mode=document.getElementById('incidentStyle')?.value||'heatmap';
 const dataset=document.getElementById('incidentDataset')?.value||'damage';
 if(dataset==='layered'||(dataset==='both'&&mode==='areas')){
  const affected=properties.filter(reportedIncident);
  const unaffectedProperties=properties.filter(unaffectedIncident);
  if(mode==='areas'){
   // Defined incident areas: draw each dataset independently, retaining both
   // boundaries in overlapping areas. These are exploratory clusters, not
   // property boundaries or proven HS2 impact zones.
   const drawDefinedAreas=(records,kind)=>{
    if(!records.length)return;
    const coords=records.map(p=>L.latLng(+p.latitude,+p.longitude));
    const visited=new Set(),clusters=[];
    for(let i=0;i<coords.length;i++){
     if(visited.has(i))continue;
     const group=[],queue=[i];visited.add(i);
     while(queue.length){
      const j=queue.shift();group.push(j);
      for(let k=0;k<coords.length;k++)
       if(!visited.has(k)&&coords[j].distanceTo(coords[k])<=radius*1.4){visited.add(k);queue.push(k);}
     }
     clusters.push(group);
    }
    const isUnaffectedGroup=kind==='unaffected';
    clusters.forEach(group=>{
     const locations=group.map(i=>[coords[i].lng,coords[i].lat]);
     try{
      const shape=locations.length===1?turf.point(locations[0]):locations.length===2?turf.lineString(locations):turf.convex(turf.featureCollection(locations.map(x=>turf.point(x))))||turf.multiPoint(locations);
      const buffered=turf.buffer(shape,Math.max(12,radius*0.30),{units:'meters',steps:12});
      if(buffered)L.geoJSON(buffered,{pane:'incidentAreasPane',interactive:false,style:{
       color:isUnaffectedGroup?'#74206e':'#c52b35',
       weight:isUnaffectedGroup?2.8:2.5,
       dashArray:isUnaffectedGroup?'7 5':null,
       opacity:1,
       fillColor:isUnaffectedGroup?'#dc6ab1':'#ee7659',
       fillOpacity:isUnaffectedGroup?Math.min(.26,opacity*.4):Math.min(.28,opacity*.45)
      }}).addTo(incidentAreaLayer);
     }catch(err){console.warn('Could not draw layered defined incident area',err);}
    });
   };
   drawDefinedAreas(affected,'affected');
   drawDefinedAreas(unaffectedProperties,'unaffected');
   if(note)note.textContent=`Defined incident areas (${dataset==='both'?'Both — combined':'Layered comparison'}): ${affected.length} reported-damage and ${unaffectedProperties.length} explicitly unaffected properties. Solid red outlines = affected; dashed purple outlines = unaffected. These are illustrative proximity clusters, not confirmed damage boundaries.`;
   updateHs2HotspotLegend();return;
  }
  if(mode!=='heatmap'){
   if(note)note.textContent='Choose Hotspot density or Defined incident area.';
   updateHs2HotspotLegend();return;
  }
  // Draw in order: original affected heatmap underneath original unaffected heatmap.
  if(affected.length)combinedIncidentLayers.push(new SmoothIncidentDensity(
   affected.map(p=>[+p.latitude,+p.longitude]),{radiusMeters:radius,opacity}
  ).addTo(map));
  if(unaffectedProperties.length){
   const upperOpacity=Number(document.getElementById('hs2UnaffectedOpacity')?.value||45)/100;
   combinedIncidentLayers.push(new SmoothIncidentDensity(
    unaffectedProperties.map(p=>[+p.latitude,+p.longitude]),
    {radiusMeters:radius,opacity:upperOpacity,palette:'layered-unaffected'}
   ).addTo(map));
  }
  if(document.getElementById('hs2ShowContours')?.checked){
   combinedIncidentLayers.push(new HS2DensityContours(
    affected.map(p=>[+p.latitude,+p.longitude]),
    unaffectedProperties.map(p=>[+p.latitude,+p.longitude]),
    {radiusMeters:radius,threshold:Number(document.getElementById('hs2ContourThreshold')?.value||35)}
   ).addTo(map));
  }
  if(note)note.textContent=`Layered hotspots: ${affected.length} reported-damage properties underneath ${unaffectedProperties.length} explicitly unaffected properties. Affected uses its original density colours; unaffected uses cyan-to-purple. Transparency can mix colours. Optional red solid and purple dashed lines show density thresholds, not damage boundaries.`;
  updateHs2HotspotLegend();return;
 }
 if(dataset==='both'){
  const affected=properties.filter(reportedIncident);
  const unaffectedProperties=properties.filter(unaffectedIncident);
  if(mode==='heatmap'){
   // A single composited layer ensures the overlap is green, not purple.
   if(affected.length||unaffectedProperties.length){
    combinedIncidentLayers.push(new CombinedIncidentDensity(
     affected.map(p=>[+p.latitude,+p.longitude]),
     unaffectedProperties.map(p=>[+p.latitude,+p.longitude]),
     {radiusMeters:radius,opacity}
    ).addTo(map));
   }
   if(note)note.textContent=`Combined hotspots: ${affected.length} reported-damage and ${unaffectedProperties.length} unaffected properties. Red = damage; blue = unaffected; green = overlap. Concentration, not risk or causation.`;
   updateHs2HotspotLegend();
   return;
  }
  // Other display modes are not defined for the combined dataset.
  if(note)note.textContent='Choose Hotspot density or Defined incident area to view both groups.';
  updateHs2HotspotLegend();
  return;
 }
 const unaffected=dataset==='unaffected';
 const points=properties.filter(unaffected?unaffectedIncident:reportedIncident);
 const subject=unaffected?'explicitly unaffected properties':'properties with reported damage';
 if(!points.length){if(note)note.textContent=`No mapped ${subject} found. Blank Damage cells are not treated as unaffected.`;return;}
 if(mode==='heatmap'){
  // Draw a continuous density field instead of Leaflet.heat's cell-aggregated grid.
  const samples=points.map(p=>[Number(p.latitude),Number(p.longitude)]);
  incidentHeatLayer=new SmoothIncidentDensity(samples,{radiusMeters:radius,opacity}).addTo(map);
  if(note)note.textContent=`Smooth density from ${points.length} ${subject}. Colour shows concentration of records, not damage severity or HS2 causation.`;
  return;
 }
 const coords=points.map(p=>L.latLng(+p.latitude,+p.longitude));
 const visited=new Set(),clusters=[];
 for(let i=0;i<coords.length;i++){
  if(visited.has(i))continue;
  const group=[],queue=[i];visited.add(i);
  while(queue.length){
   const j=queue.shift();group.push(j);
   for(let k=0;k<coords.length;k++)
    if(!visited.has(k)&&coords[j].distanceTo(coords[k])<=radius*1.4){visited.add(k);queue.push(k);}
  }
  clusters.push(group);
 }
 const max=Math.max(1,...clusters.map(c=>c.length));
 clusters.forEach(group=>{
  const locations=group.map(i=>[coords[i].lng,coords[i].lat]);
  const fraction=group.length/max;
  const fill=fraction>=0.67?'#df3945':fraction>=0.34?'#f09b35':'#f4d35e';
  const outline=fraction>=0.67?'#ae1f2d':fraction>=0.34?'#b86b13':'#ac8a19';
  try{
   const shape=locations.length===1?turf.point(locations[0]):locations.length===2?turf.lineString(locations):turf.convex(turf.featureCollection(locations.map(x=>turf.point(x))))||turf.multiPoint(locations);
   const buffered=turf.buffer(shape,Math.max(12,radius*0.30),{units:'meters',steps:12});
   if(buffered)L.geoJSON(buffered,{pane:'incidentAreasPane',interactive:false,style:{color:outline,weight:2,opacity:0.95,fillColor:fill,fillOpacity:Math.max(0.18,Math.min(0.72,opacity))}}).addTo(incidentAreaLayer);
  }catch(err){console.warn('Could not draw incident area',err);}
 });
 if(note)note.textContent=`${points.length} ${subject}. Outlined areas group nearby properties; boundaries are illustrative.`;
}
for(const id of ['showIncidentAreas','incidentRadius','incidentOpacity','incidentStyle','incidentDataset']){
 document.getElementById(id)?.addEventListener('input',()=>{refreshIncidentAreas();updateHs2HotspotLegend();});
}
map.on('zoomend',()=>{if(document.getElementById('showIncidentAreas')?.checked&&document.getElementById('incidentStyle')?.value==='heatmap')refreshIncidentAreas();});
// Permission values are metadata, not damage classifications.
function permissionStatus(p){const x=String(p?.mappingPermission||'Not recorded').trim().toLowerCase();return x==='granted'?'Granted':x==='pending'?'Pending':x==='not granted'?'Not granted':'Not recorded'}
// Hide expressly declined properties from every normal map view.
// The permission review switch temporarily reveals all records.
function hs2PermissionVisible(p){return !!document.getElementById('showPermissionIndicators')?.checked || permissionStatus(p)!=='Not granted';}
const hs2PermissionToggle=document.createElement('label');
hs2PermissionToggle.style.cssText='display:flex;align-items:center;gap:7px;margin:9px 0';
hs2PermissionToggle.innerHTML='<input type="checkbox" id="showPermissionIndicators"> Show all recorded properties with permission indicators (administrative view)';
(document.getElementById('showHouses')?.closest('label')||document.getElementById('showHouses')?.parentElement||document.getElementById('summary')?.parentElement)?.insertAdjacentElement('afterend',hs2PermissionToggle);
hs2PermissionToggle.title='Administrative review only. When off, Not granted properties are hidden from markers, lists and hotspot layers; records remain in the dataset.';
hs2PermissionToggle.querySelector('input').addEventListener('change',()=>render());
if(!HS2_PUBLIC_DISPLAY){
 const editor=document.getElementById('pinEditor');
 const label=document.createElement('label');label.textContent='Property mapping permission ';
 const select=document.createElement('select');select.id='pinMappingPermission';
 select.innerHTML=['Not recorded','Pending','Granted','Not granted'].map(x=>'<option value="'+x+'">'+x+'</option>').join('');
 label.appendChild(select);
 (document.getElementById('pinDamage')?.closest('label')||editor).insertAdjacentElement('afterend',label);
}
function setEditorPermission(p){const el=document.getElementById('pinMappingPermission');if(el)el.value=permissionStatus(p)}
function editorPermission(){return {mappingPermission:document.getElementById('pinMappingPermission')?.value||'Not recorded'}}
function iconFor(p){
 const reviewing=document.getElementById('showPermissionIndicators')?.checked;
 const permission=permissionStatus(p);
 const noDamage=!String(p.damage||'').trim()||/^(no damage|none|nil|no damage recorded|no visible damage|non-affected|non affected|unaffected)[.!\s]*$/i.test(String(p.damage).trim());
 const colour=permission==='Granted'?'#16834b':permission==='Not granted'?'#bd2932':'#64748b';
 const label=permission==='Granted'?'Permission granted':permission==='Not granted'?'Permission not granted':permission==='Pending'?'Permission pending':'Permission not recorded';
 // Compact vector badge: equal-sized symbols, sharp strokes and a white outline.
 // Position the badge to the upper-right of the original property dot.
 const glyph=permission==='Granted'
  ?'<path d="M4.2 8.1 6.8 10.5 11.8 5.4"/>'
  :permission==='Not granted'
   ?'<path d="M5.2 5.2 10.8 10.8 M10.8 5.2 5.2 10.8"/>'
   :'<path d="M6.1 6.1a2 2 0 0 1 3.8.7c0 1.3-1.9 1.7-1.9 3 M8 12.1h.01"/>';
 const indicator=reviewing?`<span style="position:absolute;left:9px;top:-10px;width:17px;height:17px;display:block;pointer-events:none;filter:drop-shadow(0 1px 1px rgba(0,0,0,.3))" role="img" aria-label="${label}" title="${label}"><svg viewBox="0 0 16 16" width="17" height="17" aria-hidden="true" style="display:block;overflow:visible"><circle cx="8" cy="8" r="7.1" fill="${colour}" stroke="#fff" stroke-width="1.8"/><g fill="none" stroke="#fff" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${glyph}</g></svg></span>`:'';
 return L.divIcon({className:'',html:`<span class="house-marker ${p.status}${noDamage?' no-damage':''}" aria-label="${esc(p.address)}"></span>${indicator}`,iconSize:[12,12],iconAnchor:[6,6]});
}
let displayedMarkerProperties=[];
function render(skipList=false){
 refreshHotspotComparison();
 displayedMarkerProperties=[];
 measurementLayer.clearLayers();markerLayer.clearLayers();const q=document.querySelector('#search').value.toLowerCase().trim(),filter=document.querySelector('#status').value;
 let visible=0;
 properties.forEach(p=>{
  if(!hs2PermissionVisible(p))return;
  if(!isPropertyIncluded(p)&&!document.getElementById('showPermissionIndicators')?.checked)return;
  p.distance=isLocalCoordinate(p.latitude,p.longitude)?tunnelDistance(+p.latitude,+p.longitude):NaN;
  p.status=classify(p.distance);
  if(!isLocalCoordinate(p.latitude,p.longitude))return;
  const text=`${p.id} ${p.address} ${p.postcode||''} ${p.damage||''} ${p.notes||''}`.toLowerCase();
  if(!document.getElementById('showPermissionIndicators')?.checked&&q&&!text.includes(q))return;
  if(!document.getElementById('showPermissionIndicators')?.checked&&filter==='unaffected'&&!isUnaffected(p))return;
  if(!document.getElementById('showPermissionIndicators')?.checked&&filter==='very-close'&&!(p.distance<=15))return;
  if(!document.getElementById('showPermissionIndicators')?.checked&&filter==='within-30'&&!(p.distance>15&&p.distance<=30))return;
  if(!document.getElementById('showPermissionIndicators')?.checked&&filter==='outside-30'&&!(p.distance>30))return;
  // If any street disclosure is expanded, display markers only for those streets.
  // With no expanded streets, retain the normal overview of all matching properties.
  const streetKey=addressParts(p.address).street.toLocaleLowerCase('en-GB');
  if(!document.getElementById('showPermissionIndicators')?.checked&&expandedStreets.size&&!expandedStreets.has(streetKey))return;
  visible++;
  displayedMarkerProperties.push(p);
  const m=L.marker([+p.latitude,+p.longitude],{icon:iconFor(p)}).addTo(markerLayer);
  m.bindTooltip(`${esc(p.address)} — ${Number.isFinite(p.distance)?Math.round(p.distance)+' m (estimated)':'distance unavailable'}`);
  m.on('click',()=>{if(!placingPin){showDetails(p);showTunnelMeasurement(p)}});
  m.bindPopup(()=>propertyCard(p),{maxWidth:340,minWidth:240});
  m.on('popupclose',()=>{if(!measurementEnabled)measurementLayer.clearLayers();});
  m.on('popupopen',e=>{if(measurementEnabled){m.closePopup();return;}bindEditLocation(e.popup.getElement());bindPhotoButtons(e.popup.getElement());});
 });
 // Summary totals must use the same permission/visibility scope as the map.
 const summaryProperties=properties.filter(p=>hs2PermissionVisible(p)&&isPropertyIncluded(p));
 const located=summaryProperties.filter(p=>isLocalCoordinate(p.latitude,p.longitude)).length;
 const known=summaryProperties.filter(p=>isLocalCoordinate(p.latitude,p.longitude)&&Number.isFinite(tunnelDistance(+p.latitude,+p.longitude))).length;
 const permissionCounts={'Granted':0,'Not granted':0,'Pending':0,'Not recorded':0};
 properties.forEach(p=>{permissionCounts[permissionStatus(p)]++;});
 const permissionSummary=document.getElementById('showPermissionIndicators')?.checked?`<div class="hs2-permission-summary" style="margin-top:9px;padding-top:8px;border-top:1px solid #d4dce5"><strong>Property mapping permission — all ${properties.length} records</strong><br><span style="color:#16834b">✓ Granted: ${permissionCounts['Granted']}</span> · <span style="color:#b42318">× Not granted: ${permissionCounts['Not granted']}</span><br><span style="color:#64748b">? Pending: ${permissionCounts['Pending']}</span> · Not recorded: ${permissionCounts['Not recorded']}</div>`:'';
 document.querySelector('#summary').innerHTML=`<b>${visible}</b> shown of ${summaryProperties.length}<br>Located: ${located} · Unresolved: ${summaryProperties.length-located}<br>Estimated tunnel distances: ${known} · Unavailable: ${summaryProperties.length-known}${permissionSummary}`;
 refreshIncidentAreas();
 if(!skipList)renderPropertyList(q,filter);
 refreshPinOptions();
 document.dispatchEvent(new Event("hs2-properties-updated"));
}

function refreshStreetMarkers(){render(true)}

// Remember expanded streets when search/filter updates the address list.
const expandedStreets=new Set();
// Only located addresses belonging to currently expanded streets control the view.
// Closing the last street leaves the existing map view untouched.
function fitExpandedStreetAddresses(){
 const openGroups=[...document.querySelectorAll('#propertyList .street-group[open]')];
 if(!openGroups.length)return;
 const indices=openGroups.flatMap(group=>[...group.querySelectorAll('.property-row[data-i]')].map(b=>Number(b.dataset.i)));
 const points=indices.map(i=>properties[i]).filter(p=>p&&isLocalCoordinate(p.latitude,p.longitude))
   .map(p=>[Number(p.latitude),Number(p.longitude)]);
 if(!points.length)return;
 openingFitActive=false;
 if(openingFitObserver){openingFitObserver.disconnect();openingFitObserver=null;}
 clearTimeout(openingFitTimer);
 map.closePopup();map.stop();map.invalidateSize({pan:false});
 if(points.length===1)map.setView(points[0],17,{animate:true});
 else map.fitBounds(L.latLngBounds(points),{padding:[45,45],maxZoom:17,animate:true});
}

function addressParts(address){
 const value=String(address||'').trim().replace(/\s+/g,' ');
 // Number + optional suffix, then street. Keep non-numbered addresses in a group.
 const match=value.match(/^(\d+)\s*([a-z]?)\s+(.+)$/i);
 if(!match)return {street:value||'Other addresses',number:-1,suffix:'',label:value};
 return {street:match[3].trim(),number:Number(match[1]),suffix:match[2].toLowerCase(),label:value};
}
function renderPropertyList(q='',filter='all'){
 const el=document.querySelector('#propertyList');if(!el)return;
 // Administration-only totals, based on the Google Sheet's Map Visibility field.
 // Keep excluded properties out of the visible address listing.
 const heading=el.closest('section')?.querySelector('h2');
 if(heading){
  let counts=heading.querySelector('#hs2-property-visibility-counts');
  if(HS2_PUBLIC_DISPLAY){if(counts)counts.remove();}
  else{
   if(!counts){
    counts=document.createElement('small');
    counts.id='hs2-property-visibility-counts';
    counts.style.cssText='display:block;font-size:.75em;font-weight:400;margin-top:4px;color:#52637a';
    heading.appendChild(counts);
   }
   const omitted=properties.filter(p=>!isPropertyIncluded(p)).length;
   counts.textContent=`${properties.length-omitted} included · ${omitted} omitted`;
  }
 }
 const rows=properties.filter(p=>{
  if(!isPropertyIncluded(p)||!hs2PermissionVisible(p))return false;
  const text=`${p.id} ${p.address} ${p.postcode||''} ${p.damage||''} ${p.notes||''}`.toLowerCase();
  return (!q||text.includes(q))&&(filter==='all'||(filter==='unaffected'&&isUnaffected(p))||(filter==='very-close'&&p.distance<=15)||(filter==='within-30'&&p.distance>15&&p.distance<=30)||(filter==='outside-30'&&p.distance>30));
 });
 const groups=new Map();
 rows.forEach(p=>{
  const parts=addressParts(p.address);
  const key=parts.street.toLocaleLowerCase('en-GB');
  if(!groups.has(key))groups.set(key,{street:parts.street,items:[]});
  groups.get(key).items.push({p,parts});
 });
 const ordered=[...groups.entries()].sort((a,b)=>a[1].street.localeCompare(b[1].street,'en-GB',{numeric:true,sensitivity:'base'}));
 el.innerHTML=ordered.map(([key,group])=>{
  group.items.sort((a,b)=>a.parts.number-b.parts.number||a.parts.suffix.localeCompare(b.parts.suffix)||a.parts.label.localeCompare(b.parts.label,'en-GB',{numeric:true}));
  const opened=expandedStreets.has(key)||Boolean(q);
  return `<details class="street-group" data-street="${esc(key)}" ${opened?'open':''}><summary>${esc(group.street)} <span class="street-count">${group.items.length}</span></summary><div class="street-addresses">${group.items.map(({p})=>`<button type="button" class="property-row" data-i="${properties.indexOf(p)}"><strong>${esc(p.address)}</strong><span>${esc(p.postcode||'')}${p.id?' · ID '+esc(p.id):''}</span></button>`).join('')}</div></details>`;
 }).join('')||'<p class="hint">No matching addresses.</p>';
 // Respond to user interaction, not browser-generated initial <details> toggle events.
 el.querySelectorAll('.street-group > summary').forEach(summary=>summary.addEventListener('click',()=>{
  const group=summary.parentElement;
  const key=group.dataset.street;
  // Native details toggles after click; update once its open state has changed.
  setTimeout(()=>{
   if(group.open)expandedStreets.add(key);else expandedStreets.delete(key);
   // Refresh markers without rebuilding the disclosures under the pointer.
   refreshStreetMarkers();
   fitExpandedStreetAddresses();
  },0);
 }));
 el.querySelectorAll('.property-row').forEach(button=>button.addEventListener('click',()=>focusProperty(properties[+button.dataset.i])));
}

function normaliseStreet(s){return String(s||'').toLowerCase().replace(/[’']/g, "'").replace(/\b(street|st\.?)(?=\W|$)/g,'street').replace(/\b(road|rd\.?)(?=\W|$)/g,'road').replace(/\b(avenue|ave\.?)(?=\W|$)/g,'avenue').replace(/[^a-z0-9]+/g,' ').trim().replace(/\s+/g,' ')}
function matchingCaption(caption,address){
 const c=normaliseStreet(caption),a=normaliseStreet(address);
 if(!a||!c.startsWith(a))return false;
 const rest=c.slice(a.length).trim();
 // Require a word boundary; prevent 23 Parry Road matching 230 Parry Road.
 return !rest||rest.startsWith('front')||rest.startsWith('rear')||rest.startsWith('side')||rest.startsWith('crack')||rest.startsWith('damage')||rest.startsWith('wall')||rest.startsWith('window')||rest.startsWith('door')||rest.startsWith('roof')||rest.startsWith('external')||rest.startsWith('internal')||rest.startsWith('elevation')||rest.startsWith('photo')||rest.startsWith('view')||rest.startsWith('subsidence')||rest.startsWith('movement')||rest.startsWith('garden')||rest.startsWith('brick')||rest.startsWith('ceiling')||rest.startsWith('floor')||rest.startsWith('foundation')||rest.startsWith('chimney')||rest.startsWith('boundary');
}
function photoEntries(p){
 const result=[];
 for(const url of String(p.photos||'').split(/[|;\n]+/).map(x=>x.trim())){
  try{if(new URL(url).protocol==='https:')result.push({url,caption:p.address})}catch{}
 }
 for(const item of photoIndex){
  if(matchingCaption(item.caption,p.address))result.push(item);
 }
 return [...new Map(result.map(x=>[x.url,x])).values()].slice(0,24);
}
function safePhotoUrls(p){return photoEntries(p).map(x=>x.url)}
function parsePhotoIndex(csv){
 const lines=csvRecords(csv.replace(/^\uFEFF/,''));if(!lines.length)return [];
 const headers=splitCSV(lines[0]).map(normaliseHeader);
 const ci=headers.indexOf('caption'),ui=headers.findIndex(h=>['imageurl','photourl','url'].includes(h));
 if(ci<0||ui<0)throw Error('Photo index needs Caption and Image URL columns');
 return lines.slice(1).map(line=>{const v=splitCSV(line);return {caption:(v[ci]||'').trim(),url:(v[ui]||'').trim()}}).filter(x=>{try{return !!x.caption&&new URL(x.url).protocol==='https:'}catch{return false}});
}
async function loadPhotoIndex(){
 try{
  const response=await fetch('photo-index.csv?v='+Date.now(),{cache:'no-store'});
  if(!response.ok)throw Error('HTTP '+response.status);
  photoIndex=parsePhotoIndex(await response.text());
  photoIndexStatus(`${photoIndex.length} indexed photographs loaded.`);
 }catch(e){photoIndexStatus('No photograph index loaded. Shared Webador album link remains available.');}
 render();
}
function photoIndexStatus(message){const el=document.querySelector('#photoIndexStatus');if(el)el.textContent=message}
function photoAlbumLink(){
 const url=String(cfg.propertyPhotoAlbumUrl||'').trim();
 try{const u=new URL(url);if(u.protocol!=='https:')return '';return `<p class="album-link"><a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">View Property Photographs ↗</a></p>`;}catch{return '';}
}
function requestWebadorPhotos(address){
 // The parent Webador page checks the iframe source before opening its album viewer.
 if(window.parent===window){alert('Open the map on its Webador page to view the linked album.');return;}
 window.parent.postMessage({type:'hs2-qpt-open-photos',address:String(address||'')},'*');
}
// Ask the Webador parent for thumbnail previews whenever a property is displayed.
function requestWebadorPreviews(address){
 if(window.parent===window)return;
 window.parent.postMessage({type:'hs2-qpt-request-previews',address:String(address||'')},'*');
}
window.addEventListener('message',event=>{
 if(event.source!==window.parent||!event.data||event.data.type!=='hs2-qpt-photo-previews')return;
 // The reply must come from the page that embeds this map.
 try{if(document.referrer&&event.origin!==new URL(document.referrer).origin)return;}catch{return;}
 const address=String(event.data.address||'');
 const photos=Array.isArray(event.data.photos)?event.data.photos.slice(0,3):[];
 document.querySelectorAll('.hs2-live-previews').forEach(box=>{
  if(box.dataset.address!==address)return;
  box.replaceChildren();
  if(!photos.length){box.textContent='No matching Webador photographs yet.';return;}
  photos.forEach(photo=>{
   let url;try{url=new URL(photo.thumb);if(url.protocol!=='https:')return;}catch{return;}
   const button=document.createElement('button');button.type='button';button.className='hs2-preview-tile';
   button.title=String(photo.caption||'View photographs');
   const img=document.createElement('img');img.src=url.href;img.alt=String(photo.caption||'Property photograph');img.loading='lazy';
   button.appendChild(img);button.addEventListener('click',()=>requestWebadorPhotos(address));box.appendChild(button);
  });
 });
});
function bindPhotoButtons(scope){
 if(!scope)return;
 const previews=scope.querySelector('.hs2-live-previews');if(previews)requestWebadorPreviews(previews.dataset.address);
 scope.querySelectorAll('.hs2-webador-gallery').forEach(button=>{
  button.addEventListener('click',()=>requestWebadorPhotos(button.dataset.address));
 });
}
function propertyCard(p){
 const distance=Number.isFinite(p.distance)?Math.round(p.distance)+' metres (estimated)':'Not available';
 const photos=photoEntries(p);
 const gallery=photos.length?`<div class="property-gallery">${photos.map((photo,i)=>`<a href="${esc(photo.url)}" target="_blank" rel="noopener noreferrer" aria-label="Open property photo ${i+1}: ${esc(photo.caption)}"><img src="${esc(photo.url)}" alt="${esc(photo.caption)}" loading="lazy" referrerpolicy="no-referrer" onerror="this.parentElement.style.display='none'"><small>${esc(photo.caption)}</small></a>`).join('')}</div>`:'<p class="hint">No indexed photographs for this property yet.</p>';
 return `<div class="property-card"><h3>${esc(p.address)}</h3><p><strong>Location:</strong> ${esc(p.address)}${p.postcode?', '+esc(p.postcode):''}</p><p><strong>Property ID:</strong> ${esc(p.id)}</p><p><strong>Mapping permission:</strong> ${esc(permissionStatus(p))}</p><p><strong>Distance from tunnel:</strong> ${distance}</p><p><strong>Coordinates:</strong> ${Number.isFinite(+p.latitude)&&Number.isFinite(+p.longitude)?Number(p.latitude).toFixed(6)+', '+Number(p.longitude).toFixed(6):'Unavailable'}</p>${p.notes?`<p>${esc(p.notes)}</p>`:''}<h4>Damage recorded</h4><p class="damage-description">${p.damage?esc(p.damage).replace(/^(no damage|none|nil|no damage recorded|no visible damage|unaffected)$/i,'Non-affected').replace(/\r?\n/g,'<br>'):'Non-affected'}</p><h4>Associated photographs</h4><div class="hs2-live-previews" data-address="${esc(p.address)}" aria-label="Webador photograph previews"><span class="hint">Loading Webador photographs…</span></div><button type="button" class="hs2-webador-gallery" data-address="${esc(p.address)}">View property photographs</button><p class="hint">Opens the Webador album viewer when displayed on the QPT website.</p>${gallery}${photoAlbumLink()}<button type="button" class="edit-location" data-property-id="${esc(p.id)}" data-property-address="${esc(p.address)}">Edit location on map</button><p class="hint">Tunnel geometry is provisional. Distance is horizontal and does not establish eligibility or safeguarding status.</p></div>`;
}
function showDetails(p){document.querySelector('#details').innerHTML='<h2>Selected property</h2>'+propertyCard(p);bindEditLocation(document.querySelector('#details'));bindPhotoButtons(document.querySelector('#details'))}
function focusProperty(p,zoom=19){
 if(!p)return;
 showDetails(p);
 if(!isLocalCoordinate(p.latitude,p.longitude)){
  pinMsg('This property has no confirmed map coordinates. Select it in the Pinpoint Editor and place its marker manually.');
  return;
 }
 const lat=Number(p.latitude),lon=Number(p.longitude);
 // Leaflet popup autoPan used to move the map away from the chosen pinpoint.
 // Disable it so the selected house stays exactly in the map centre.
 map.closePopup();
 map.stop();
 map.invalidateSize({pan:false});
 map.setView(L.latLng(lat,lon),zoom,{animate:false,reset:true});
 const popup=L.popup({maxWidth:340,minWidth:240,autoPan:false,keepInView:false})
  .setLatLng([lat,lon]).setContent(propertyCard(p)).openOn(map);
 if(popup.getElement()){bindEditLocation(popup.getElement());bindPhotoButtons(popup.getElement());}
 // Keep the pinpoint centred even when the map is inside a resizing Webador iframe.
 requestAnimationFrame(()=>{
  map.invalidateSize({pan:false});
  map.panTo([lat,lon],{animate:false});
 });
}

function splitCSV(line){let out=[],v='',q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){v+='"';i++}else q=!q}else if(c===','&&!q){out.push(v.trim());v=''}else v+=c}out.push(v.trim());return out}
// Preserve quoted line breaks in free-text fields such as Damage.
function csvRecords(text){let records=[],start=0,quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"')i++;else quoted=!quoted;}else if((c==='\n'||c==='\r')&&!quoted){const line=text.slice(start,i);if(line.trim())records.push(line);if(c==='\r'&&text[i+1]==='\n')i++;start=i+1;}}const last=text.slice(start);if(last.trim())records.push(last);return records;}
function normaliseHeader(x){return String(x||'').toLowerCase().trim().replace(/[ _-]+/g,'')}
function parseCSV(text){const lines=csvRecords(text.replace(/^\uFEFF/,''));if(lines.length<2)throw Error('The sheet has no data rows.');const raw=splitCSV(lines[0]);const aliases={id:['id','propertyid','ref','reference'],address:['address','propertyaddress','houseaddress'],postcode:['postcode','postalcode','zip'],latitude:['latitude','lat'],longitude:['longitude','lng','lon','long'],notes:['notes','note','comments','comment'],damage:['damage','damagedescription','propertydamage'],photos:['photos','photourls','photo','images','imageurls','photolinks'],mapVisibility:['mapvisibility','visibility','includeonmap'],claimReported:['claimreported','claimsubmitted','claimmade'],claimResult:['claimresult','claimoutcome','claimstatus'],mappingPermission:['mappingpermission','propertymappingpermission','permission','publicationpermission']};const idx={};raw.forEach((h,i)=>{const n=normaliseHeader(h);for(const [key,vals] of Object.entries(aliases))if(vals.includes(n))idx[key]=i});if(idx.address===undefined)throw Error('Missing required column: Address.');const rows=[];lines.slice(1).forEach((line,i)=>{const a=splitCSV(line);if(!a.some(Boolean))return;const get=k=>idx[k]===undefined?'':(a[idx[k]]??'').trim();if(!get('address'))return;const lat=parseFloat(get('latitude')),lon=parseFloat(get('longitude'));rows.push({id:get('id')||String(rows.length+1).padStart(2,'0'),address:get('address'),postcode:get('postcode'),latitude:Number.isFinite(lat)?lat:null,longitude:Number.isFinite(lon)?lon:null,notes:get('notes'),damage:get('damage'),claimReported:get('claimReported'),claimResult:get('claimResult'),mappingPermission:get('mappingPermission')||'Not recorded',photos:get('photos'),mapVisibility:get('mapVisibility')||'Included',rowNumber:i+2})});if(!rows.length)throw Error('No usable property rows were found.');return rows}
const GEOCODE_CACHE_VERSION='v3';
const QP_BOUNDS={south:51.515,north:51.555,west:-0.245,east:-0.165};
function isLocalCoordinate(lat,lon){lat=+lat;lon=+lon;return Number.isFinite(lat)&&Number.isFinite(lon)&&lat>=QP_BOUNDS.south&&lat<=QP_BOUNDS.north&&lon>=QP_BOUNDS.west&&lon<=QP_BOUNDS.east}
function cacheKey(p){return 'hs2qp:geocode:'+GEOCODE_CACHE_VERSION+':'+String(p.address+' '+(p.postcode||'')).toLowerCase().replace(/\s+/g,' ').trim()}
function readGeocodeCache(p){try{const v=JSON.parse(localStorage.getItem(cacheKey(p)));if(v&&isLocalCoordinate(v.lat,v.lon)){p.latitude=v.lat;p.longitude=v.lon;return true}}catch(e){}return false}
function saveGeocodeCache(p){try{localStorage.setItem(cacheKey(p),JSON.stringify({lat:+p.latitude,lon:+p.longitude,display:p.geocodeDisplay||'',saved:Date.now()}))}catch(e){}}
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function geocodeOne(p){const query=[p.address,p.postcode,'London','UK'].filter(Boolean).join(', ');const base=cfg.geocoderUrl||'https://nominatim.openstreetmap.org/search';const url=base+'?format=jsonv2&limit=1&countrycodes=gb&q='+encodeURIComponent(query);const res=await fetch(url,{headers:{'Accept':'application/json'}});if(!res.ok)throw Error('Geocoder HTTP '+res.status);const data=await res.json();if(!data.length)return false;const lat=Number(data[0].lat),lon=Number(data[0].lon);if(!isLocalCoordinate(lat,lon))return false;p.latitude=lat;p.longitude=lon;p.geocodeDisplay=data[0].display_name||'';saveGeocodeCache(p);return true}
async function resolveMissingCoordinates(rows){const missing=rows.filter(p=>!isLocalCoordinate(p.latitude,p.longitude));missing.forEach(readGeocodeCache);const todo=missing.filter(p=>!isLocalCoordinate(p.latitude,p.longitude));if(!todo.length)return {resolved:missing.length,failed:[]};const failed=[];for(let i=0;i<todo.length;i++){const p=todo[i];setDataStatus(`Locating address ${i+1} of ${todo.length}: ${p.address}${p.postcode?' · '+p.postcode:''}…`,'loading');try{if(!await geocodeOne(p))failed.push(p)}catch(e){failed.push(p)}if(i<todo.length-1)await sleep(Math.max(1100,cfg.geocodeDelayMs||1100))}return {resolved:missing.length-failed.length,failed}}
function isPropertyIncluded(p){return !/^excluded$/i.test(String(p.mapVisibility||'').trim())}
function validProperties(){return properties.filter(p=>isPropertyIncluded(p)&&hs2PermissionVisible(p)&&isLocalCoordinate(p.latitude,p.longitude))}
function showUnresolved(failed){const el=document.querySelector('#unresolved');if(!failed.length){el.innerHTML='';return}el.innerHTML=`<details open><summary>${failed.length} address${failed.length===1?'':'es'} could not be located</summary><ul>${failed.map(p=>`<li>${esc(p.address)}${p.postcode?' · '+esc(p.postcode):''}</li>`).join('')}</ul><p class=\"hint\">Check the spelling/postcode in the Google Sheet, then click Reload Google Sheet.</p></details>`}

function setDataStatus(message,kind=''){const el=document.querySelector('#dataStatus');el.textContent=message;el.className='data-status '+kind}
function sheetCsvUrl(){return cfg.spreadsheetId?`https://docs.google.com/spreadsheets/d/${encodeURIComponent(cfg.spreadsheetId)}/export?format=csv&gid=${encodeURIComponent(cfg.sheetGid||'0')}`:''}
// Fit the opening view to all located properties, including when the Webador
// iframe changes dimensions after the map has loaded.
let openingFitActive=true;
let openingFitObserver=null;
let openingFitTimer=null;
function fitAll(){
 const pts=validProperties().map(p=>[Number(p.latitude),Number(p.longitude)]);
 if(!pts.length)return;
 if(HS2_PUBLIC_DISPLAY && hs2SettingsReady){hs2ApplyPublicSettings();return;}
 openingFitActive=true;
 const bounds=L.latLngBounds(pts);
 const applyFit=()=>{
   if(!openingFitActive)return;
   const el=map.getContainer();
   if(el.clientWidth<100||el.clientHeight<100)return;
   map.invalidateSize({pan:false,debounceMoveend:true});
   if(pts.length===1)map.setView(pts[0],17,{animate:false});
   else map.fitBounds(bounds,{
     paddingTopLeft:[35,35],paddingBottomRight:[35,35],
     maxZoom:16,animate:false
   });
 };
 if(openingFitObserver)openingFitObserver.disconnect();
 clearTimeout(openingFitTimer);
 applyFit();
 requestAnimationFrame(()=>requestAnimationFrame(applyFit));
 openingFitObserver=new ResizeObserver(()=>{if(openingFitActive)applyFit();});
 openingFitObserver.observe(map.getContainer());
 openingFitTimer=setTimeout(()=>{
   applyFit();openingFitActive=false;
   openingFitObserver.disconnect();openingFitObserver=null;
 },2500);
}
async function loadGoogleSheet(){const url=sheetCsvUrl();if(!url){setDataStatus('No Google Sheet is configured.','error');return}setDataStatus('Loading properties from Google Sheet…','loading');try{const res=await fetch(url,{cache:'no-store'});if(!res.ok)throw Error(`Google returned HTTP ${res.status}`);properties=parseCSV(await res.text());applyManualPins();const geo=await resolveMissingCoordinates(properties);render();fitAll();if(HS2_PUBLIC_DISPLAY)hs2SettingsLoad.then(hs2ApplyPublicSettings);showUnresolved(geo.failed);setDataStatus(`${properties.length} properties loaded from Google Sheet · ${validProperties().length} located · ${new Date().toLocaleString('en-GB')}`,'ok')}catch(err){properties=[];render();showUnresolved([]);setDataStatus(`Google Sheet could not be loaded: ${err.message}. No sample properties are displayed. Check Sheet sharing or import a CSV.`, 'error')}}
async function loadRoute(){
  tunnelLayer.clearLayers(); zoneLayer.clearLayers(); corridorLayer.clearLayers(); routeLines=[];
  try{
    const res=await fetch('hs2-route.geojson?updated='+Date.now(),{cache:'no-store'});
    if(!res.ok) throw Error('HTTP '+res.status);
    let fc=await res.json();
    try { const id=localStorage.getItem(ACTIVE_ROUTE_KEY); const item=JSON.parse(localStorage.getItem(ROUTES_KEY)||'[]').find(r=>r.id===id); const saved=item?.feature; if(saved?.geometry && (saved.geometry.type==='LineString'||saved.geometry.type==='MultiLineString')) fc={type:'FeatureCollection',features:[saved,...(fc.features||[]).filter(f=>f.geometry?.type==='Polygon'||f.geometry?.type==='MultiPolygon')]}; } catch(e){}
    const route=fc.features.find(f=>f.geometry&&(f.geometry.type==='LineString'||f.geometry.type==='MultiLineString'));
    const zone=fc.features.find(f=>f.geometry&&(f.geometry.type==='Polygon'||f.geometry.type==='MultiPolygon'));
    if(route){
      routeFeature=route;
      routeLines=route.geometry.type==='MultiLineString'?route.geometry.coordinates.map(line=>line.map(c=>[c[1],c[0]])):[route.geometry.coordinates.map(c=>[c[1],c[0]])];
      L.geoJSON(route,{style:{color:'#142e63',weight:3,opacity:1,lineCap:'round'}}).addTo(tunnelLayer);
      // Turf computes a true geographic 30 metre buffer, not a pixel-width stroke.
      if(window.turf && typeof turf.buffer==='function'){
        const corridor=turf.buffer(route,30,{units:'meters',steps:32});
        L.geoJSON(corridor,{style:{color:'#315b9c',weight:1.5,opacity:.75,fillColor:'#648cc8',fillOpacity:.28},interactive:false}).addTo(corridorLayer);
      }
    }
    if(zone){
      L.geoJSON(zone,{style:{color:'#1f5f99',weight:2,opacity:.9,fillColor:'#4f91c7',fillOpacity:.22}}).addTo(zoneLayer);
    }
    document.querySelector('#showTunnel').checked=true;
    document.querySelector('#showZone').checked=false;
    document.querySelector('#showCorridor').checked=true;
    if(!map.hasLayer(tunnelLayer))tunnelLayer.addTo(map);
    if(map.hasLayer(zoneLayer))map.removeLayer(zoneLayer);
    if(!map.hasLayer(corridorLayer))corridorLayer.addTo(map);
    document.querySelector('#routeStatus').textContent='Blue shading is an indicative 30 m buffer around each selected tunnel bore (overlaps may merge visually). A manually traced line is not official HS2 geometry or an eligibility boundary.';
  }catch(err){
    document.querySelector('#routeStatus').textContent='HS2 vector layer could not be loaded: '+err.message;
  }
  render();
}
