// Manual pinpoints: explicit browser-local overrides, never silently written to Google Sheets.
function storedPins(){try{return JSON.parse(localStorage.getItem(MANUAL_KEY)||'{}')}catch{return {}}}
function pinKey(p){return String(p.id||'').trim()+'|'+String(p.address||'').trim().toLowerCase()}
function matchSavedPin(p,pins){
 const id=String(p.id||'').trim();
 // Stable ID first, so a renamed street does not produce a duplicate property.
 if(id){const found=Object.values(pins).find(v=>String(v.id||'').trim()===id);if(found)return found}
 return pins[pinKey(p)];
}
function applyManualPins(){
 const pins=storedPins(), matched=new Set();
 properties.forEach(p=>{
  const override=matchSavedPin(p,pins);
  if(override){/* The Sheet is authoritative for Map Visibility on existing rows. */Object.assign(p,{address:override.address||p.address,postcode:override.postcode??p.postcode,notes:override.notes??p.notes,mappingPermission:override.mappingPermission??p.mappingPermission});
   if(isLocalCoordinate(override.latitude,override.longitude)){p.latitude=override.latitude;p.longitude=override.longitude;p.locationSource='manual'}
   matched.add(pinKey(override));
  }
 });
 Object.entries(pins).forEach(([key,p])=>{
  if(!matched.has(key)&&!properties.some(v=>String(v.id||'')===String(p.id||'')&&p.id)&&isLocalCoordinate(p.latitude,p.longitude))properties.push({...p,locationSource:'manual'});
 });
}
function persistProperty(original,updated){
 const pins=storedPins(), oldKey=original?pinKey(original):null;
 if(oldKey)delete pins[oldKey];
 // Also discard stale entries for this ID to prevent reappearance on reload.
 if(updated.id)for(const [key,value] of Object.entries(pins))if(String(value.id||'')===String(updated.id))delete pins[key];
 pins[pinKey(updated)]={...updated};
 localStorage.setItem(MANUAL_KEY,JSON.stringify(pins));
 if(original)Object.assign(original,updated);else properties.push(updated);
}
function refreshPinOptions(){
 const sel=document.querySelector('#pinProperty');if(!sel)return;
 const old=sel.value;
 sel.innerHTML='<option value="new">+ New property</option>'+properties.map((p,i)=>`<option value="${i}">${esc(p.address)}${p.postcode?' ('+esc(p.postcode)+')':''}</option>`).join('');
 sel.value=(old==='new'||old===''||!Number.isInteger(+old)||+old>=properties.length)?'new':old;
 updateRemoveLocalButton();
}
function selectedLocalProperty(){
 const selected=document.querySelector('#pinProperty').value;
 return selected==='new'?null:properties[Number(selected)]||null;
}
function localPropertyMatches(p,pins){
 if(!p)return [];
 const norm=v=>String(v??'').trim().toLowerCase().replace(/\s+/g,' ');
 const id=norm(p.id);
 const address=norm(p.address);
 // An ID is the unique identity. Never delete a different ID just
 // because it has the same street address.
 return Object.entries(pins).filter(([key,v])=>{
   const savedId=norm(v.id);
   const keyId=norm(key.split('|')[0]);
   if(id)return savedId===id || (!savedId && keyId===id);
   // For records with no ID, require an exact key match; do not
   // delete every property sharing an address.
   return !savedId && norm(key)===norm(pinKey(p)) && !!address;
 });
}
// Compatibility with older index.html versions: restore the missing removal control.
// Do this before binding its click handler, otherwise a missing element aborts
// all subsequent pinpoint-editor event registration.
(function ensureRemoveLocalButton(){
 const editor=document.getElementById('pinEditor');
 if(!editor||document.getElementById('removeLocalProperty'))return;
 const button=document.createElement('button');
 button.id='removeLocalProperty';
 button.type='button';
 button.textContent='Remove locally saved property';
 button.disabled=true;
 const anchor=document.getElementById('cancelPin');
 if(anchor)anchor.insertAdjacentElement('afterend',button);
 else editor.appendChild(button);
})();
// Visibility is controlled only from the manual address editor; the Sheet remains authoritative.
(function(){
 const field=document.getElementById('pinDamage');
 if(!field||document.getElementById('pinMapVisibility'))return;
 const label=document.createElement('label');label.textContent='Show property on map: ';
 const select=document.createElement('select');select.id='pinMapVisibility';
 select.innerHTML='<option value="Included">Included</option><option value="Excluded">Excluded</option>';
 label.appendChild(select);
 (field.closest('label')||field).insertAdjacentElement('afterend',label);
})();
function setEditorVisibility(p){const el=document.getElementById('pinMapVisibility');if(el)el.value=isPropertyIncluded(p||{})?'Included':'Excluded'}
function editorVisibility(){return document.getElementById('pinMapVisibility')?.value||'Included'}
function setEditorClaims(p){
 document.getElementById('pinClaimReported').value=p?.claimReported||'';
 document.getElementById('pinClaimResult').value=p?.claimResult||'';
}
function editorClaims(){
 return {claimReported:document.getElementById('pinClaimReported').value,
         claimResult:document.getElementById('pinClaimResult').value};
}
function updateRemoveLocalButton(){
 const button=document.querySelector('#removeLocalProperty');
 if(!button)return;
 const p=selectedLocalProperty();
 // Do not disable for a selected property: the editor may show a Sheet row
 // while the local record uses a different saved identifier.
 button.disabled=!p;
 button.title=p?'Check for and remove this property’s locally saved record. Google Sheets is unchanged.':'Select a property first.';
}
document.querySelector('#removeLocalProperty')?.addEventListener('click',async()=>{
 const sel=document.querySelector('#pinProperty');
 const p=selectedLocalProperty();
 if(!p){pinMsg('Select a property from the dropdown first.');return;}
 const pins=storedPins();
 const matches=localPropertyMatches(p,pins);
 if(!matches.length){pinMsg('No locally saved record matched '+p.address+'. Nothing was deleted.');return;}
 if(!confirm('Remove '+matches.length+' locally saved record(s) for '+p.address+' (Property ID: '+(p.id||'not assigned')+')?\n\nOther property IDs and Google Sheets will not be changed.'))return;
 for(const [key] of matches)delete pins[key];
 try{localStorage.setItem(MANUAL_KEY,JSON.stringify(pins))}catch(e){pinMsg('Could not remove local property: '+e.message);return;}
 stopPin();sel.value='new';
 for(const id of ['pinAddress','pinPostcode','pinNotes','pinDamage'])document.querySelector('#'+id).value='';setEditorClaims(null);
 pinMsg('Local record removed. Reloading properties…');
 if(cfg.useGoogleSheet!==false)await loadGoogleSheet();
 else {properties=properties.filter(v=>v!==p);render();}
 pinMsg('Locally saved record removed. If it is still in Google Sheets, the Sheet version remains.');
});
function pinMsg(s){document.querySelector('#pinMessage').textContent=s}
function stopPin(){
 placingPin=false;map.getContainer().style.cursor='';
 if(draftPin){map.removeLayer(draftPin);draftPin=null}
 document.querySelector('#savePin').disabled=true;document.querySelector('#cancelPin').disabled=true;
}
function selectPropertyForEditing(index){
 if(HS2_PUBLIC_DISPLAY)return;
 const p=properties[index];if(!p)return;
 stopPin();document.querySelector('#pinProperty').value=String(index);updateRemoveLocalButton();
 document.querySelector('#pinAddress').value=p.address;
 document.querySelector('#pinPostcode').value=p.postcode||'';
 document.querySelector('#pinNotes').value=p.notes||'';document.querySelector('#pinDamage').value=p.damage||'';setEditorVisibility(p);setEditorClaims(p);setEditorPermission(p);
 if(isLocalCoordinate(p.latitude,p.longitude))focusProperty(p);
 pinMsg('Selected '+p.address+'. Click Place pinpoint on map to correct its location.');
 document.querySelector('#pinEditor').scrollIntoView({behavior:'smooth',block:'start'});
}
function bindEditLocation(container){
 if(HS2_PUBLIC_DISPLAY)return;
 container.querySelectorAll('.edit-location').forEach(b=>b.addEventListener('click',()=>{
  const i=properties.findIndex(p=>String(p.id)===b.dataset.propertyId&&p.address===b.dataset.propertyAddress);
  if(i>=0)selectPropertyForEditing(i);
 }));
}
document.querySelector('#pinProperty').addEventListener('change',e=>{
 updateRemoveLocalButton();
 const p=properties[+e.target.value];if(e.target.value==='new'||!p){document.querySelector('#pinAddress').value='';document.querySelector('#pinPostcode').value='';document.querySelector('#pinNotes').value='';document.querySelector('#pinDamage').value='';setEditorVisibility(null);setEditorClaims(null);setEditorPermission(null);return}
 document.querySelector('#pinAddress').value=p.address;document.querySelector('#pinPostcode').value=p.postcode||'';document.querySelector('#pinNotes').value=p.notes||'';document.querySelector('#pinDamage').value=p.damage||'';setEditorVisibility(p);setEditorClaims(p);setEditorPermission(p);
 focusProperty(p);
});
document.querySelector('#saveDetails').addEventListener('click',()=>{
 const chosen=document.querySelector('#pinProperty').value;
 if(chosen==='new'){pinMsg('Select an existing property to edit its street name, or place a pinpoint for a new property.');return}
 const original=properties[+chosen];if(!original)return;
 const address=document.querySelector('#pinAddress').value.trim();
 if(!address){pinMsg('Please enter the street address.');return}
 const updated={...original,address,postcode:document.querySelector('#pinPostcode').value.trim(),notes:document.querySelector('#pinNotes').value.trim(),damage:document.querySelector('#pinDamage').value.trim(),...editorClaims(),...editorPermission(),mapVisibility:editorVisibility()};
 try{persistProperty(original,updated)}catch(e){pinMsg('Could not save in this browser: '+e.message);return}
 render();if(isPropertyIncluded(updated))focusProperty(updated);pinMsg('Street name and property details saved locally. Export CSV to update your Google Sheet.');
});
document.querySelector('#startPin').addEventListener('click',()=>{
 if(!document.querySelector('#pinAddress').value.trim()){pinMsg('Enter an address first.');return}
 stopPin();placingPin=true;map.getContainer().style.cursor='crosshair';
 document.querySelector('#cancelPin').disabled=false;
 const i=document.querySelector('#pinProperty').value;const p=i==='new'?null:properties[+i];
 if(p&&isLocalCoordinate(p.latitude,p.longitude)){
  draftPin=L.marker([+p.latitude,+p.longitude],{draggable:true,autoPan:true}).addTo(map);
  draftPin.bindTooltip('Drag this marker, or click another building').openTooltip();
  document.querySelector('#savePin').disabled=false;
  map.setView([+p.latitude,+p.longitude],19);
  pinMsg('Drag the existing pinpoint or click a new position on the map, then save.');
 }else pinMsg('Click the building on the map to place the pinpoint.');
});
map.on('click',e=>{
 if(!placingPin)return;
 if(!isLocalCoordinate(e.latlng.lat,e.latlng.lng)){pinMsg('Choose a location in the Queen’s Park area.');return}
 if(draftPin)map.removeLayer(draftPin);
 draftPin=L.marker(e.latlng,{draggable:true,autoPan:true}).addTo(map);
 draftPin.bindTooltip('Drag to refine the position').openTooltip();
 document.querySelector('#savePin').disabled=false;
 pinMsg('Drag the temporary marker if necessary, then select Save pinpoint locally.');
});
document.querySelector('#cancelPin').addEventListener('click',()=>{stopPin();pinMsg('Pinpoint placement cancelled.')});
document.querySelector('#savePin').addEventListener('click',()=>{
 if(!placingPin||!draftPin)return;
 const address=document.querySelector('#pinAddress').value.trim(),postcode=document.querySelector('#pinPostcode').value.trim();
 if(!address){pinMsg('Address is required.');return}
 const loc=draftPin.getLatLng();
 const chosen=document.querySelector('#pinProperty').value;
 const original=chosen==='new'?null:properties[+chosen];
 const id=original?.id||'M'+Date.now().toString(36).toUpperCase();
 const p={...(original||{}),id,address,postcode,notes:document.querySelector('#pinNotes').value.trim(),damage:document.querySelector('#pinDamage').value.trim(),...editorClaims(),...editorPermission(),mapVisibility:editorVisibility(),latitude:+loc.lat.toFixed(7),longitude:+loc.lng.toFixed(7),locationSource:'manual'};
 try{persistProperty(original,p)}catch(e){pinMsg('Browser storage failed: '+e.message);return}
 stopPin();render();if(isPropertyIncluded(p))focusProperty(p);
 pinMsg('Pinpoint saved in this browser. Download CSV to back it up and share it.');
});
function csvCell(v){const s=String(v??'');return '"'+s.replace(/"/g,'""')+'"'}
function propertyCsv(){
 const headers=['ID','Address','Postcode','Latitude','Longitude','Notes','Damage','Claim Reported','Claim Result','Photos','Location Source','Map Visibility','Mapping Permission'];
 const rows=properties.map(p=>[p.id,p.address,p.postcode,p.latitude??'',p.longitude??'',p.notes,p.damage||'',p.claimReported||'',p.claimResult||'',p.photos,p.locationSource||'geocoded',isPropertyIncluded(p)?'Included':'Excluded',permissionStatus(p)]);
 return '\uFEFF'+[headers,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n');
}
function showCsvFallback(csv){
 const panel=document.querySelector('#csvFallback');
 document.querySelector('#csvText').value=csv;
 panel.hidden=false;
 document.querySelector('#csvText').focus();
 pinMsg('CSV ready. If Safari does not download it, use Copy CSV or select the text and paste into a spreadsheet.');
}
document.querySelector('#exportPins').addEventListener('click',()=>{
 const csv=propertyCsv();
 // Data URL avoids Safari's blob: navigation/WebKitBlobResource error.
 // Keep the visible copy fallback for browsers that open the CSV as text.
 showCsvFallback(csv);
 const a=document.createElement('a');
 a.href='data:text/csv;charset=utf-8,'+encodeURIComponent(csv);
 a.download='hs2-property-pinpoints.csv';
 a.style.display='none';document.body.appendChild(a);
 try{a.click()}catch(e){pinMsg('Automatic download blocked. Use Copy CSV below.');}
 a.remove();
});
document.querySelector('#copyCsv').addEventListener('click',async()=>{
 const t=document.querySelector('#csvText');
 try{await navigator.clipboard.writeText(t.value);pinMsg('CSV copied. Paste it into a text file or spreadsheet.');}
 catch(e){t.focus();t.select();pinMsg('Press Command+C to copy the selected CSV, then paste into a text file or spreadsheet.');}
});

